const ACADEMY_KEY='schritt-academy-v1';
const blankAcademy=()=>({version:1,plan:{minutes:20,days:5,target:'A2',examDate:''},daily:[],official:[],compact:[],active:null});
let academy=blankAcademy(),academyTimer=null;
try{const v=JSON.parse(localStorage.getItem(ACADEMY_KEY));if(v?.version===1&&Array.isArray(v.daily)&&Array.isArray(v.official)&&Array.isArray(v.compact))academy={...academy,...v};}catch{}
function saveAcademy(){try{localStorage.setItem(ACADEMY_KEY,JSON.stringify(academy));}catch{showModal('<h3>لم يتم حفظ جلسة التدريب</h3><p>صدّر نسخة كاملة قبل الإغلاق؛ مساحة المتصفح قد تكون غير متاحة.</p>');}}
function localDay(){return new Date().toLocaleDateString('en-CA');}
function historyStreak(days,today=localDay()){const seen=new Set(days);const date=new Date(today+'T12:00:00');let n=0;if(!seen.has(today))date.setDate(date.getDate()-1);for(let i=0;i<3650;i++){const key=date.toLocaleDateString('en-CA');if(!seen.has(key))break;n++;date.setDate(date.getDate()-1);}return n;}
function academySummary(){return {days:new Set(academy.daily.map(x=>x.day)).size,streak:historyStreak(academy.daily.map(x=>x.day)),compact:academy.compact.length,official:academy.official.length};}
function dailyPlan(){const level=state.level;const weak=allWords().filter(w=>itemStat(w.id).status===2&&w.level===level).length;return [{title:weak?'ابدأ بالكلمات التي أخطأت فيها':'استرجع الكلمات المستحقة',route:'review',minutes:Math.max(2,Math.round(academy.plan.minutes*.2))},{title:'قاعدة واحدة ثم جملتان من عندك',route:'grammarBook',minutes:Math.max(2,Math.round(academy.plan.minutes*.2))},{title:'استماع أو قراءة في سياق',route:'examCenter',minutes:Math.max(3,Math.round(academy.plan.minutes*.3))},{title:'تحدّث ثم اكتب خلاصة قصيرة',route:'dialogues',minutes:Math.max(3,Math.round(academy.plan.minutes*.3))}];}
navs.splice(1,0,['studyPlan','خطتي اليومية']);navs.splice(navs.length-1,0,['examCenter','مركز الامتحانات'],['dialogues','مواقف وحوار']);for(const k of ['studyPlan','examCenter','dialogues'])icons[k]=icons.paths;
EXTRA_VIEWS.studyPlan=studyPlan;EXTRA_VIEWS.examCenter=examCenter;EXTRA_VIEWS.dialogues=dialogues;EXTRA_VIEWS.examRun=examRun;
const homeBeforeAcademy=home;
home=function(){homeBeforeAcademy();const s=academySummary(),box=document.createElement('section');box.className='new-hero';box.innerHTML=`<h2>تعلّم يوميًا. اختبر نفسك بجدية.</h2><p>${s.streak} يومًا متتاليًا • ${s.compact} تدريب مهارات مكتملًا • ${s.official} نموذجًا رسميًا مسجلًا</p><div class="actions"><button class="primary" id="open-plan3">مهمة اليوم</button><button class="secondary" id="open-exams3">مركز الامتحانات ←</button></div>`;$('#app').prepend(box);$('#open-plan3').onclick=()=>go('studyPlan');$('#open-exams3').onclick=()=>go('examCenter');};
function studyPlan(){const s=academySummary(),done=academy.daily.some(d=>d.day===localDay());$('#app').innerHTML=viewHead('خطة تنفعك في الكلام والامتحان','دروس قصيرة ذات هدف، ومراجعة للأخطاء، وإنتاج جمل من ذاكرتك. اختر وقتًا تقدر تلتزم به.')+`<div class="stats"><div class="stat"><div><small>تتابع الدراسة</small><strong>${s.streak}</strong><span class="unit">يوم</span></div></div><div class="stat"><div><small>الهدف اليومي</small><strong>${academy.plan.minutes}</strong><span class="unit">دقيقة</span></div></div><div class="stat"><div><small>المستوى المستهدف</small><strong>${esc(academy.plan.target)}</strong></div></div><div class="stat"><div><small>أيام الدراسة المسجلة</small><strong>${s.days}</strong></div></div></div><div class="panel"><form id="plan-form3" class="form-grid"><label>وقت الدراسة بالدقائق<select name="minutes">${[10,15,20,30,45,60].map(n=>`<option ${academy.plan.minutes===n?'selected':''}>${n}</option>`).join('')}</select></label><label>أيام أسبوعيًا<select name="days">${[3,4,5,6,7].map(n=>`<option ${academy.plan.days===n?'selected':''}>${n}</option>`).join('')}</select></label><label>المستوى المستهدف<select name="target">${['A1','A2','B1','B2'].map(l=>`<option ${academy.plan.target===l?'selected':''}>${l}</option>`).join('')}</select></label><label>موعد امتحانك إن حُدد<input name="examDate" type="date" value="${esc(academy.plan.examDate)}"></label><button class="primary">احفظ خطتي</button></form><p class="subtle">لا نحسب موعد إتقان مضمون من دقائق الدراسة. الخطة تنظيم شخصي؛ التقدم يقاس بالأداء في المهارات.</p></div><div class="lesson-grid" style="margin-top:20px">${dailyPlan().map((task,i)=>`<article class="panel"><span class="badge">مهمة ${i+1} • نحو ${task.minutes} د</span><h3>${task.title}</h3><button class="secondary" data-route3="${task.route}">ابدأ ←</button><label><input type="checkbox" data-daily3> أنجزت المهمة — تسجيل ذاتي</label></article>`).join('')}</div><div class="panel" style="margin-top:20px"><h3>بعد جلسة ${state.level}… أقدر:</h3>${CAN_DO[state.level].map(t=>`<p><label><input type="checkbox" data-can3> ${t}</label></p>`).join('')}<div class="actions"><button class="primary" id="complete-day3" ${done?'disabled':''}>${done?'تم تسجيل جلسة اليوم':'سجّل إنجاز جلسة اليوم'}</button></div><p id="daily-feedback3" class="subtle" aria-live="polite">سجل الإنجاز ذاتي ولا يثبت إتقان المستوى.</p></div>`;$('#plan-form3').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);academy.plan={minutes:+f.get('minutes'),days:+f.get('days'),target:f.get('target'),examDate:f.get('examDate')};saveAcademy();studyPlan();};document.querySelectorAll('[data-route3]').forEach(b=>b.onclick=()=>go(b.dataset.route3));$('#complete-day3').onclick=()=>{const checks=[...document.querySelectorAll('[data-daily3]')];if(checks.some(c=>!c.checked)){$('#daily-feedback3').textContent='أكمل المهام الأربع أو ارجع لها قبل تسجيل إنجاز اليوم.';return;}if(!academy.daily.some(d=>d.day===localDay()))academy.daily.push({day:localDay(),level:state.level,minutes:academy.plan.minutes,time:Date.now(),self:true});saveAcademy();studyPlan();};}

let examLevel=state.level;
function examCenter(){const p=EXAM_PROFILES[examLevel];$('#app').innerHTML=viewHead('مركز الامتحانات','أربع مهارات، ووقت محدد، ونتيجة تفصل التصحيح الآلي عن التقييم الذاتي. ابدأ بالمستوى المناسب لك.')+`<div class="toolbar"><select id="exam-level3" aria-label="مستوى الامتحان">${Object.keys(EXAM_PROFILES).map(l=>`<option ${l===examLevel?'selected':''}>${l}</option>`).join('')}</select>${academy.active?'<button class="primary" id="resume-exam3">استكمل تدريبك المحفوظ</button>':''}<button class="secondary" id="record-official3">سجّل نتيجة نموذج رسمي</button></div><div class="source-grid"><article class="panel"><span class="badge">المعيار الأصلي</span><h3>نماذج Goethe الرسمية</h3><p>افتح النموذج الرسمي والصوت من المصدر. استخدم المؤقت لتدريب كل جزء، ثم سجّل نتيجتك بمفتاح الإجابة أو بتقييم المدرّس. هذا هو المرجع المباشر لشكل الاختبار وصعوبته.</p><a class="primary" target="_blank" rel="noopener" href="${p.official}">افتح مواد ${examLevel} الرسمية ↗</a><p><a target="_blank" rel="noopener" href="${p.info}">الوصف الرسمي للامتحان ↗</a></p><div class="table-wrap"><table class="data-table"><tr><th>الجزء</th><th>المدة الرسمية</th><th>مؤقت مستقل</th></tr>${Object.entries(p.minutes).map(([k,v])=>`<tr><td>${k}</td><td>${v} دقيقة</td><td><button class="text-link" data-official-timer3="${k}">ابدأ</button></td></tr>`).join('')}</table></div><p class="subtle">مدد الأجزاء وفق صفحات Goethe للبالغين، راجعت في ١٤ نوفمبر ٢٠٢٦. اتبع ملف النموذج في عدد مرات الاستماع والإعداد والانتقالات؛ المؤقت وحده لا يعيد تنفيذ قواعد الامتحان.</p></article><article class="panel"><span class="badge">محتوى أصلي من خطوة</span><h3>تدريب مهارات قصير — ${examLevel}</h3><p>٥ أسئلة قراءة و٥ استماع، ثم مهمة كتابة ومهمة كلام. الزمن أقصر من الرسمي، والأسئلة لم تُعايَر لتطابق صعوبته. مناسب لاكتشاف نقاط الضعف قبل النموذج الكامل.</p><div class="notice amber">الاستماع بصوت الجهاز وليس تسجيلًا رسميًا. لا درجة آلية للكتابة أو النطق، ولا شهادة جاهزية مبنية على الاختيارات وحدها.</div><button class="primary" id="start-compact3">ابدأ التدريب المتدرّج ←</button><p class="subtle">الترتيب يتغير؛ المحتوى من بنك ثابت معلن: ٨ نصوص و٤٠ سؤال فهم موزعة على المستويات الأربعة.</p></article></div><div class="panel" style="margin-top:20px"><h3>سجل النماذج الرسمية</h3>${academy.official.length?`<div class="table-wrap"><table class="data-table"><tr><th>المستوى والنموذج</th><th>Lesen</th><th>Hören</th><th>Schreiben</th><th>Sprechen</th><th>المصدر</th></tr>${academy.official.slice().reverse().slice(0,15).map(r=>`<tr><td>${r.level} / ${esc(r.name)}</td>${['Lesen','Hören','Schreiben','Sprechen'].map(k=>`<td>${r.scores[k]===null?'بانتظار التقييم':r.scores[k]+'%'}</td>`).join('')}<td>${r.evaluator==='teacher'?'الكتابة والكلام: مدرّس':'تسجيل/تقييم ذاتي'}</td></tr>`).join('')}</table></div>`:'<p class="subtle">لم تسجل نموذجًا رسميًا بعد.</p>'}<p class="notice">${readinessText(examLevel)}</p><h3>آخر تدريبات المهارات القصيرة</h3>${academy.compact.slice().reverse().slice(0,8).map(r=>`<div class="record"><span class="badge">${r.level}</span><span>قراءة ${r.read}/5 • استماع ${r.listen}/5</span><span class="subtle">الكتابة والكلام: تقييم ذاتي • ${new Date(r.time).toLocaleDateString('ar-EG')}</span></div>`).join('')||'<p class="subtle">لا توجد تدريبات مكتملة.</p>'}</div>`;$('#exam-level3').onchange=e=>{examLevel=e.target.value;examCenter();};$('#start-compact3').onclick=()=>{if(academy.active){showModal('<h3>عندك تدريب غير مكتمل</h3><p>استكمله أولًا، أو اختر استبداله. النتائج المكتملة لن تتغير.</p><button class="primary" id="replace-compact3">استبدل الجلسة غير المكتملة</button>');$('#replace-compact3').onclick=()=>{academy.active=null;startCompact(examLevel);};}else startCompact(examLevel);};if($('#resume-exam3'))$('#resume-exam3').onclick=()=>go('examRun');$('#record-official3').onclick=recordOfficial;document.querySelectorAll('[data-official-timer3]').forEach(b=>b.onclick=()=>officialTimer(b.dataset.officialTimer3,p.minutes[b.dataset.officialTimer3]));}
function readinessText(level){const trials=academy.official.filter(r=>r.level===level);const complete=trials.filter(r=>Object.values(r.scores).every(Number.isFinite));const teacher=complete.filter(r=>r.evaluator==='teacher');if(!complete.length)return 'الجاهزية لم تُقيّم بعد: تحتاج نموذجًا رسميًا كاملًا ودرجات المهارات الأربع. نتيجة الكلمات وحدها لا تكفي.';if(!teacher.length)return 'عندك نتائج كاملة مسجلة ذاتيًا؛ راجع الكتابة والكلام مع مدرّس قبل الاعتماد عليها لتحديد الجاهزية.';const distinct=new Set(teacher.map(r=>r.name.trim().toLowerCase())).size;return `لديك ${complete.length} نموذجًا كاملًا، منها ${teacher.length} بتقييم مدرّس للكتابة والكلام و${distinct} أسماء نماذج مختلفة. راقب ثبات الأداء في كل مهارة؛ الموقع لا يصدر قرار نجاح أو جاهزية رسميًا.`;}
function recordOfficial(){modalWide(`<h2>سجل نموذج Goethe الرسمي</h2><p class="subtle">حوّل الدرجات إلى نسبة مئوية وفق مفتاح النموذج ومعايير التصحيح. لا ندخل نتيجة ناقصة كصفر، ولا نحسب نجاحًا رسميًا هنا.</p><form id="official-form3" class="form-grid"><label>المستوى<select name="level">${Object.keys(EXAM_PROFILES).map(l=>`<option ${l===examLevel?'selected':''}>${l}</option>`).join('')}</select></label><label>اسم النموذج المميز<input required maxlength="100" name="name" placeholder="مثلًا: A1 Modellsatz Erwachsene"></label>${['Lesen','Hören','Schreiben','Sprechen'].map(k=>`<label>${k} — من ١٠٠، أو اتركه فارغًا<input name="${k}" type="number" min="0" max="100" step="0.1"></label>`).join('')}<label class="full">من قيّم الكتابة والكلام؟<select name="evaluator"><option value="self">تقييم ذاتي / لم يُقيّما بعد</option><option value="teacher">مدرّس قيّم الكتابة والكلام معًا</option></select></label><button class="primary">احفظ النتيجة</button></form>`);$('#official-form3').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),scores={};for(const k of ['Lesen','Hören','Schreiben','Sprechen']){const v=f.get(k);scores[k]=v===''?null:Number(v);if(scores[k]!==null&&(!Number.isFinite(scores[k])||scores[k]<0||scores[k]>100))return;}const evaluator=f.get('evaluator');if(evaluator==='teacher'&&(scores.Schreiben===null||scores.Sprechen===null)){showModal('<h3>درجة غير مكتملة</h3><p>اختيار تقييم المدرّس للمهارتين يحتاج تسجيل درجتي الكتابة والكلام.</p>');return;}academy.official.push({id:'official-'+Date.now(),level:f.get('level'),name:f.get('name').trim(),scores,evaluator,time:Date.now()});saveAcademy();$('#modal').hidden=true;examCenter();};}
let officialDeadline=null;
function officialTimer(skill,minutes){officialDeadline=Date.now()+minutes*60000;modalWide(`<h2>مؤقت ${skill} — ${examLevel}</h2><div class="score" id="official-clock3">${minutes}:00</div><p>افتح مادة Goethe الرسمية في تبويب آخر. الوقت يستمر عند مغادرة هذا التبويب؛ لا يوجد إيقاف في هذه المحاولة.</p><a class="secondary" target="_blank" rel="noopener" href="${EXAM_PROFILES[examLevel].official}">النموذج الرسمي ↗</a><p id="official-status3" class="subtle">المؤقت مساعد مستقل؛ لا يسجل إجابات النموذج الخارجي.</p>`);}
function startCompact(level){$('#modal').hidden=true;academy.active={id:'compact-'+Date.now(),level,index:0,orderRead:shuffle([0,1,2,3,4]),orderListen:shuffle([0,1,2,3,4]),answers:{read:{},listen:{}},writing:'',speaking:'',plays:0,deadline:Date.now()+EXAM_PROFILES[level].readMinutes*60000,started:Date.now(),selfChecks:{writing:[],speaking:[]}};saveAcademy();go('examRun');}
function activeRemaining(){return academy.active?Math.max(0,Math.ceil((academy.active.deadline-Date.now())/1000)):0;}
function clockString(seconds){return `${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;}
function stageName(){return ['read','listen','writing','speaking'][academy.active?.index||0];}
function scorePart(a,kind){const qs=SKILL_BANK[a.level][kind].questions;return qs.reduce((n,q,i)=>n+(a.answers[kind][i]===q[2]?1:0),0);}
function advanceCompact(expired=false){const a=academy.active;if(!a)return;stopExamMic();a.expired=a.expired||[];if(expired)a.expired.push(stageName());if(a.index<3){a.index++;const p=EXAM_PROFILES[a.level],minutes=[p.readMinutes,p.listenMinutes,p.writeMinutes,p.speakMinutes][a.index];a.deadline=Date.now()+minutes*60000;saveAcademy();if(view==='examRun')examRun();}else{academy.compact.push({...a,read:scorePart(a,'read'),listen:scorePart(a,'listen'),time:Date.now(),type:'original-compact',selfEvaluated:true});academy.active=null;saveAcademy();if(view==='examRun')compactResult(academy.compact.at(-1));}}
function examRun(){const a=academy.active;if(!a){examCenter();return;}const stage=stageName(),bank=SKILL_BANK[a.level],task=bank[stage],part=a.index;$('#app').innerHTML=`<div class="exercise"><div class="panel"><div class="section-title"><span class="badge">${a.level} • ${part+1}/4 • تدريب قصير أصلي</span><strong id="compact-clock3" class="inline-de">${clockString(activeRemaining())}</strong></div><div class="morph">${['Lesen','Hören','Schreiben','Sprechen'].map((s,i)=>`<span class="badge">${i===part?'← ':''}${s}</span>`).join('')}</div><div id="compact-body3"></div><div class="actions"><button id="submit-part3" class="primary">${part===3?'إنهاء التدريب':'تسليم الجزء والانتقال ←'}</button><button id="leave-part3" class="secondary">ارجع للمركز — الوقت يستمر</button></div><p class="subtle">الإجابات تُحفظ محليًا. لا تصحيح ولا نماذج إجابة قبل التسليم. انتهاء الوقت ينقل للجزء التالي.</p></div></div>`;
if(stage==='read'||stage==='listen'){const content=stage==='read'?`<div class="notice de" lang="de">${esc(task.text)}</div>`:`<div class="notice">استماع مولّد بصوت الجهاز. النص مخفي حتى النتيجة. حد الاستماع مرتان؛ عدم وجود صوت لا يعني صفرًا في مستواك.</div><button id="play-listen3" class="secondary" ${a.plays>=2?'disabled':''}>اسمع (${a.plays}/2)</button><p id="listen-status3" class="subtle"></p>`;const order=stage==='read'?a.orderRead:a.orderListen;$('#compact-body3').innerHTML=`<h2 class="de">${task.title}</h2>${content}${order.map((qi,num)=>{const q=task.questions[qi];return `<fieldset style="border:1px solid #e2e8dc;border-radius:9px;padding:14px;margin:16px 0"><legend class="de">${num+1}. ${esc(q[0])}</legend>${q[1].map((op,oi)=>`<label class="de" style="display:block;margin:10px 0"><input type="radio" name="q3-${qi}" data-q3="${qi}" value="${oi}" ${a.answers[stage][qi]===oi?'checked':''}> ${esc(op)}</label>`).join('')}</fieldset>`;}).join('')}`;document.querySelectorAll('[data-q3]').forEach(r=>r.onchange=()=>{a.answers[stage][+r.dataset.q3]=+r.value;saveAcademy();});if(stage==='listen')$('#play-listen3').onclick=()=>{const voices='speechSynthesis'in window?speechSynthesis.getVoices().filter(v=>v.lang.startsWith('de')&&v.localService):[];if(!voices.length){$('#listen-status3').textContent='لا يوجد صوت ألماني محلي جاهز؛ افحص مختبر النطق أو استخدم صوت Goethe الرسمي من المركز.';return;}a.plays++;saveAcademy();const utterance=new SpeechSynthesisUtterance(task.text);utterance.lang='de-DE';utterance.voice=voices[0];utterance.rate=a.level==='A1'?.85:a.level==='A2'?.92:1;speechSynthesis.cancel();speechSynthesis.speak(utterance);$('#play-listen3').textContent=`اسمع (${a.plays}/2)`;$('#play-listen3').disabled=a.plays>=2;};}
else{const w=task[0];$('#compact-body3').innerHTML=`<h2 class="de">${w.title}</h2><div class="notice de" lang="de">${esc(w.prompt)}</div><p class="subtle">${stage==='writing'?'اكتب نصك بالألماني؛ عدد الكلمات للتوجيه وليس درجة لغة.':'تكلم بصوتك ثم دوّن ملخصًا. يمكنك تسجيل محاولة مؤقتة للمقارنة بعد التسليم.'}</p>${stage==='speaking'?'<div class="actions"><button id="exam-rec3" class="secondary">سجّل محاولة</button><button id="exam-stop3" class="secondary" disabled>أوقف التسجيل</button></div><p id="exam-mic3" class="subtle"></p><audio id="exam-audio3" controls hidden style="width:100%"></audio>':''}<textarea id="production3" class="note-editor" lang="de" placeholder="Dein Text …">${esc(a[stage])}</textarea><p id="wordcount3" class="subtle"></p><p class="notice amber">لن نمنح درجة آلية لهذا النص أو للصوت. قارن بالنموذج بعد التسليم أو اعرضه على مدرّس.</p>`;const update=()=>{a[stage]=$('#production3').value.slice(0,30000);$('#wordcount3').textContent=wordCount(a[stage])+' كلمة';saveAcademy();};$('#production3').oninput=update;update();if(stage==='speaking'){$('#exam-rec3').onclick=startExamMic;$('#exam-stop3').onclick=stopExamMic;}}
$('#submit-part3').onclick=()=>advanceCompact();$('#leave-part3').onclick=()=>{stopExamMic();go('examCenter');};}
function wordCount(text){return String(text).trim()?String(text).trim().split(/\s+/).length:0;}
function compactResult(r){const bank=SKILL_BANK[r.level];$('#app').innerHTML=viewHead('نتيجة تدريب المهارات القصير','القراءة والاستماع محسوبان من الإجابات؛ الكتابة والكلام يحتاجان مراجعة نوعية.')+`<div class="stats"><div class="stat"><div><small>Lesen</small><strong>${r.read}/5</strong></div></div><div class="stat"><div><small>Hören</small><strong>${r.listen}/5</strong></div></div><div class="stat"><div><small>Schreiben</small><b>بانتظار تقييم</b></div></div><div class="stat"><div><small>Sprechen</small><b>بانتظار تقييم</b></div></div></div><p class="notice">هذا تدريب مختصر أصلي، وليس نموذج Goethe أو اختبار تحديد مستوى مُعايَر. لا نستنتج النجاح الرسمي أو المستوى من عشر إجابات.</p><div class="source-grid">${['read','listen'].map(kind=>`<article class="panel"><h3>${kind==='read'?'القراءة':'الاستماع'} — دليل الإجابة</h3><details><summary>اعرض النص</summary><p class="de">${esc(bank[kind].text)}</p></details>${bank[kind].questions.map((q,i)=>`<div class="record"><div><b class="de">${r.answers[kind][i]===q[2]?'✓':'↻'} ${esc(q[0])}</b><p class="de subtle">${esc(q[1][q[2]])}</p><small class="de">الدليل: ${esc(q[3])}</small></div></div>`).join('')}</article>`).join('')}</div>${['writing','speaking'].map(kind=>`<section class="panel" style="margin-top:20px"><h3>${kind==='writing'?'كتابتك':'ملخص كلامك'} — مقارنة لا درجة آلية</h3><p class="de">${esc(r[kind]||'لم يُكتب نص')}</p><details><summary>اعرض نموذجًا ممكنًا</summary><p class="de">${esc(bank[kind][0].model)}</p></details><p class="subtle">راجع هذه الجوانب مع نفسك أو مع المدرّس:</p>${bank[kind][0].points.map(t=>`<p>□ ${t}</p>`).join('')}<p class="subtle">أضف فحص الترابط والدقة والمفردات، وفي الكلام الوضوح والتفاعل. ليست هذه القائمة جدول درجات Goethe الرسمي.</p></section>`).join('')}<div class="actions"><button class="primary" id="back-exams3">ارجع للمركز</button><button class="secondary" id="export-attempt3">نزّل المحاولة لعرضها على المدرّس</button></div>`;$('#back-exams3').onclick=()=>go('examCenter');$('#export-attempt3').onclick=()=>downloadJSON({schema:'schritt-skill-attempt-v1',attempt:r},'schritt-skill-attempt.json');}
let examMicStream=null,examMicRecorder=null,examMicURL=null,examMicTimeout=null,examMicGeneration=0;
async function startExamMic(){const gen=++examMicGeneration;try{if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw Error('التسجيل غير مدعوم هنا');const acquired=await navigator.mediaDevices.getUserMedia({audio:true});if(gen!==examMicGeneration||view!=='examRun'||stageName()!=='speaking'){acquired.getTracks().forEach(t=>t.stop());return;}examMicStream=acquired;const chunks=[],recording=new MediaRecorder(acquired);examMicRecorder=recording;recording.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recording.onstop=()=>{acquired.getTracks().forEach(t=>t.stop());examMicStream=null;if(gen===examMicGeneration&&$('#exam-audio3')&&view==='examRun'){if(examMicURL)URL.revokeObjectURL(examMicURL);examMicURL=URL.createObjectURL(new Blob(chunks,{type:recording.mimeType||'audio/webm'}));$('#exam-audio3').src=examMicURL;$('#exam-audio3').hidden=false;$('#exam-rec3').disabled=false;$('#exam-stop3').disabled=true;$('#exam-mic3').textContent='التسجيل مؤقت ولن يدخل النسخة الاحتياطية. لا تقييم آلي للنطق.';}};recording.start();$('#exam-rec3').disabled=true;$('#exam-stop3').disabled=false;$('#exam-mic3').textContent='جارٍ التسجيل؛ حتى ٩٠ ثانية.';examMicTimeout=setTimeout(stopExamMic,90000);}catch{$('#exam-mic3')&&($('#exam-mic3').textContent='تعذر التسجيل. راجع دعم المتصفح والسياق الآمن والإذن؛ يمكنك التدرب بصوتك دون تسجيل.');}}
function stopExamMic(){clearTimeout(examMicTimeout);if(examMicRecorder?.state==='recording')examMicRecorder.stop();if(examMicStream){examMicStream.getTracks().forEach(t=>t.stop());examMicStream=null;}}
const stopMediaBeforeAcademy=stopMedia;
stopMedia=function(){stopExamMic();examMicGeneration++;if(examMicURL){URL.revokeObjectURL(examMicURL);examMicURL=null;}stopMediaBeforeAcademy();};
function dialogues(){$('#app').innerHTML=viewHead('مواقف وحوار… لهدف واضح','اختر موقفًا، جرّب الرد من غير نموذج، ثم قارن. هذا حوار موجّه من بنك ثابت، وليس شريك ذكاء اصطناعي.')+`<div class="toolbar">${levelTabs()}<a class="secondary" target="_blank" rel="noopener" href="https://www.busuu.com/">افتح Busuu لتكمل درسك ↗</a></div><div class="source-grid">${SKILL_BANK[state.level].speaking.map((s,i)=>`<article class="panel"><span class="badge">${state.level} • هدف تواصلي</span><h3 class="de">${s.title}</h3><p class="de">${s.prompt}</p><button class="primary" id="dialogue-task3-${i}">تدرّب بدون نموذج</button></article>`).join('')}<article class="panel"><h3>دوّر الموقف في أربع خطوات</h3><p class="word-notes">١. قل ردًا أوليًا من ذاكرتك.<br>٢. غيّر الوقت أو المكان أو السبب.<br>٣. أضف سؤال متابعة.<br>٤. جرّب الرد على اعتراض أو طلب توضيح.</p><p class="subtle">قيّم هل أنجزت الهدف وهل استطاع شخص آخر فهمك؛ حفظ النص وحده لا يكفي.</p></article></div>`;SKILL_BANK[state.level].speaking.forEach((s,i)=>$('#dialogue-task3-'+i).onclick=()=>{modalWide(`<h2 class="de">${s.title}</h2><p class="de">${s.prompt}</p><textarea class="note-editor" id="dialogue-draft3" placeholder="Schreib deine Antwort …"></textarea><div class="actions"><button class="primary" id="compare-dialogue3">قارن بعد المحاولة</button></div><div id="dialogue-model3"></div><p class="subtle">نص هذه المحاولة لا يُحفظ تلقائيًا؛ انقل جملك المهمة إلى دفتر الجمل.</p>`);$('#compare-dialogue3').onclick=()=>{$('#dialogue-model3').innerHTML=`<p class="de notice">${s.model}</p><p>${s.points.join(' • ')}</p><button class="secondary" data-say-extra="${esc(s.model)}">اسمع النموذج</button>`;bind();};});}

// Complete backup now includes academy data; legacy v2 backups remain importable.
const downloadBeforeAcademy=downloadJSON;
downloadJSON=function(obj,name){if(obj.schema==='schritt-backup-v2')obj={...obj,academy};downloadBeforeAcademy(obj,name);};
function validateAcademy(v){if(v==null)return blankAcademy();if(v.version!==1||!v.plan||!Array.isArray(v.daily)||!Array.isArray(v.official)||!Array.isArray(v.compact)||v.daily.length>10000||v.official.length>2000||v.compact.length>2000)throw Error('بيانات الأكاديمية غير صالحة');if(![10,15,20,30,45,60].includes(v.plan.minutes)||![3,4,5,6,7].includes(v.plan.days)||!EXAM_PROFILES[v.plan.target])throw Error('خطة غير صالحة');if(v.official.some(r=>!EXAM_PROFILES[r.level]||typeof r.name!=='string'||!r.scores||['Lesen','Hören','Schreiben','Sprechen'].some(k=>r.scores[k]!==null&&(!Number.isFinite(r.scores[k])||r.scores[k]<0||r.scores[k]>100))))throw Error('درجات غير صالحة');if(v.compact.some(r=>!EXAM_PROFILES[r.level]||!Number.isFinite(r.read)||!Number.isFinite(r.listen)||!r.answers||typeof r.writing!=='string'||typeof r.speaking!=='string'))throw Error('محاولة غير صالحة');return JSON.parse(JSON.stringify({...v,active:null}));}
restoreBackup=function(){modalWide('<h2>استرجاع النسخة الكاملة</h2><p>تشمل الكلمات والتقدم وخطة الدراسة وسجل الامتحانات. ستستبدل البيانات الحالية بعد تأكيدك. الجلسة غير المكتملة لا تُستأنف من النسخة المستوردة.</p><input id="academy-restore3" type="file" accept=".json"><div id="academy-restore-feedback3"></div>');$('#academy-restore3').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>20000000)throw Error('الملف كبير');const raw=JSON.parse(await f.text()),v=validateBackup(raw),a=validateAcademy(raw.academy);$('#academy-restore-feedback3').innerHTML=`<p>نسخة صالحة: ${v.extra.words.length} كلمة شخصية، ${a.official.length} نموذجًا رسميًا.</p><button class="primary" id="confirm-academy-restore3">استبدل البيانات بهذه النسخة</button>`;$('#confirm-academy-restore3').onclick=()=>{state=v.base;extra=v.extra;academy=a;save();saveExtra();saveAcademy();$('#modal').hidden=true;go('progress');};}catch(err){$('#academy-restore-feedback3').textContent='تعذر الاسترجاع: '+err.message;}};};
academyTimer=setInterval(()=>{if(officialDeadline&&$('#official-clock3')&&!$('#modal').hidden){const left=Math.max(0,Math.ceil((officialDeadline-Date.now())/1000));$('#official-clock3').textContent=clockString(left);if(!left){$('#official-status3').textContent='انتهى وقت هذا الجزء.';officialDeadline=null;}}if(academy.active){const left=activeRemaining();if(view==='examRun'&&$('#compact-clock3'))$('#compact-clock3').textContent=clockString(left);if(!left)advanceCompact(true);}},1000);
window.addEventListener('pagehide',stopExamMic);
const hash3=location.hash.slice(1);if(EXTRA_VIEWS[hash3])view=hash3;render();
